1. Bootstrap 씬 — 전역 서비스 등록

게임 전체 수명 동안 유지되는 서비스를 Bootstrap 씬에서 등록합니다.

// 전역 서비스 설치자
public class GlobalInstaller : AchEngineInstaller
{
    [SerializeField] private GameConfig _config;

    public override void Install(IServiceBuilder builder)
    {
        builder
            // 설정 데이터
            .RegisterInstance<IGameConfig>(_config)
            // 테이블 데이터 서비스
            .Register<ITableService, TableService>()
            // UI 서비스 (자동 등록되지만 명시도 가능)
            .Register<IUIService, UIService>()
            // 사운드, 네트워크 등 전역 서비스
            .Register<IAudioService, AudioService>()
            .Register<INetworkService, NetworkService>();
    }
}

[Bootstrap 씬]
 └── [AchEngineScope]  Installers: [GlobalInstaller]
 └── [UIRoot]

2. 씬 전환 — Lobby → InGame

씬 단위로 별도 AchEngineScope를 두어 씬 전용 서비스를 등록·해제합니다.

// Bootstrap 씬에 등록하는 전역 씬 서비스
public class SceneService : ISceneService
{
    public async Task LoadLobby()
    {
        // 기존 게임 씬 언로드
        await UnloadCurrentGameScene();

        // Lobby 씬을 Additive로 로드
        await SceneManager.LoadSceneAsync("Lobby", LoadSceneMode.Additive);

        // 로비 진입 UI 표시
        ServiceLocator.Resolve<IUIService>().Show<LobbyView>();
    }

    public async Task LoadInGame(int stageId)
    {
        // 로비 UI 닫기
        ServiceLocator.Resolve<IUIService>().CloseAll();

        // 로비 씬 언로드 → InGame 씬 로드
        await SceneManager.UnloadSceneAsync("Lobby");
        await SceneManager.LoadSceneAsync("InGame", LoadSceneMode.Additive);

        // 게임 시작
        ServiceLocator.Resolve<IGameService>().StartStage(stageId);
    }
}

// Lobby 씬 전용 설치자
public class LobbyInstaller : AchEngineInstaller
{
    public override void Install(IServiceBuilder builder)
    {
        builder
            .Register<IShopService, ShopService>()
            .Register<IFriendService, FriendService>();
    }
}

// InGame 씬 전용 설치자
public class GameInstaller : AchEngineInstaller
{
    public override void Install(IServiceBuilder builder)
    {
        builder
            .Register<IGameService, GameService>()
            .Register<IEnemySpawner, EnemySpawner>()
            .Register<IStageService, StageService>();
    }
}

3. 팝업 생성 — 데이터 전달

팝업은 UIView를 상속하고, Show() 콜백으로 데이터를 주입합니다.

// 아이템 상세 팝업
public class ItemDetailPopup : UIView
{
    [SerializeField] private Text _nameText;
    [SerializeField] private Text _descText;
    [SerializeField] private Text _priceText;
    [SerializeField] private Image _iconImage;

    private ItemData _item;
    private string _iconAddress;

    public override UILayerId Layer => UILayerId.Popup;

    protected override void OnInitialize()
    {
        // 닫기 버튼 등 한 번만 세팅
    }

    // 외부에서 데이터 주입 (Show 콜백에서 호출)
    public void SetItem(ItemData item, Sprite icon, string iconAddress)
    {
        if (!string.IsNullOrEmpty(_iconAddress))
            AddressableManager.Release(_iconAddress);

        _item = item;
        _iconAddress = iconAddress;
        _nameText.text  = LocalizationManager.Get(L.Item.Name(item.Id));
        _descText.text  = LocalizationManager.Get(L.Item.Desc(item.Id));
        _priceText.text = $"{item.Price:N0} G";
        _iconImage.sprite = icon;
    }

    protected override void OnClosed()
    {
        _item = null;
        _iconImage.sprite = null;

        if (!string.IsNullOrEmpty(_iconAddress))
        {
            AddressableManager.Release(_iconAddress);
            _iconAddress = null;
        }
    }
}

// 팝업 열기 (인벤토리 등에서 호출)
var ui   = ServiceLocator.Resolve<IUIService>();
var iconAddress = $"icon_{item.Id}";
var icon = await AddressableManager.LoadAsync<Sprite>(iconAddress);

ui.Show<ItemDetailPopup>(popup => popup.SetItem(item, icon, iconAddress));

4. 데이터 서빙 — Table → Service

TableService가 베이크된 데이터를 래핑하고, 다른 서비스가 이를 주입받아 사용합니다.

// 게임 서비스
public class GameService : IGameService
{
    private readonly ITableService _tables;
    private readonly IUIService    _ui;

    // DI 생성자 주입
    public GameService(ITableService tables, IUIService ui)
    {
        _tables = tables;
        _ui     = ui;
    }

    public void StartStage(int stageId)
    {
        var stageData = _tables.Get<StageTable>().Get(stageId);
        var enemies   = _tables.Get<EnemyTable>().GetByStage(stageId);

        _ui.Show<GameHUDView>(hud => hud.SetStage(stageData));

        foreach (var enemy in enemies)
            SpawnEnemy(enemy);
    }
}

5. 인게임 — MonoBehaviour에서 접근

MonoBehaviour는 DI 컨테이너가 직접 생성하지 않으므로 ServiceLocator를 사용합니다.

// 플레이어 컨트롤러
public class PlayerController : MonoBehaviour
{
    private IGameService   _gameService;
    private IAudioService  _audioService;

    private void Start()
    {
        // ServiceLocator로 런타임 조회
        _gameService  = ServiceLocator.Resolve<IGameService>();
        _audioService = ServiceLocator.Resolve<IAudioService>();
    }

    private void OnTriggerEnter(Collider other)
    {
        if (other.TryGetComponent<IEnemy>(out var enemy))
        {
            _gameService.OnPlayerHit(enemy.Damage);
            _audioService.PlaySFX("hit");
        }
    }
}

전체 흐름 요약

앱 시작
 └── Bootstrap 씬 로드
      └── AchEngineScope → GlobalInstaller → 전역 서비스 등록
           └── ServiceLocator 초기화

씬 전환
 └── ISceneService.LoadLobby()
      └── Lobby 씬 additive 로드
           └── LobbyScope → LobbyInstaller → 로비 서비스 추가 등록

팝업
 └── IUIService.Show<ItemDetailPopup>(popup => popup.SetItem(...))

인게임
 └── MonoBehaviour → [Inject] 속성 주입

다음 단계

전체 모듈 연계 예시

AchEngineInstaller 자세히 보기

ServiceLocator는 VContainer 없이 런타임에 서비스를 타입으로 조회하는 정적 파사드입니다.

API

namespace AchEngine.DI
{
    public static class ServiceLocator
    {
        // 컨테이너가 준비되었는지 여부
        public static bool IsReady { get; }

        // 서비스 조회 (없으면 InvalidOperationException)
        public static T Resolve<T>();

        // 안전한 서비스 조회 (없으면 false 반환)
        public static bool TryResolve<T>(out T result);
    }
}

사용 예시

// 기본 조회
var ui = ServiceLocator.Resolve<IUIService>();
ui.Show<MainMenuView>();

// 안전한 조회
if (ServiceLocator.TryResolve<IAudioService>(out var audio))
{
    audio.PlayBGM("main_theme");
}

// 준비 여부 확인
if (!ServiceLocator.IsReady)
{
    Debug.LogWarning("서비스 컨테이너가 아직 초기화되지 않았습니다.");
    return;
}

[Inject] vs ServiceLocator

[Inject]	ServiceLocator
VContainer	✅ 필요	❌ VContainer 미설치 시만 사용 가능
사용 위치	DI 컨테이너가 생성한 객체	어디서든 (VContainer 없는 환경)
권장 상황	모든 서비스·View	VContainer 없는 MonoBehaviour
테스트 용이성	높음	중간

수동 초기화 (VContainer 없는 경우)

VContainer 없이 ServiceLocator를 사용하려면 엔진 내부에서 Setup()이 호출됩니다.
직접 호출하는 퍼블릭 API는 제공되지 않으며, AchEngineScope와 같은 내부 부트스트랩 코드가
컨테이너 준비 시 자동으로 연결합니다.

관련 문서

DI 시스템 개요

DI 라이프사이클 설계

AchEngine ECS 모듈은 Unity Entities의 World, EntityManager, EntityCommandBuffer, Baker, SystemBase를 얇게 감싼 편의 API입니다.

com.unity.entities 패키지가 설치되어 있으면 AchEngine.ECS 어셈블리가 자동으로 활성화됩니다.

using AchEngine.ECS;
using Unity.Entities;

언제 사용하나요?

타입	용도
AchSystemBase	SystemBase에서 CommandBuffer와 Query 헬퍼를 짧게 사용
AchBaker<TAuthoring>	Baker에서 Primary Entity에 컴포넌트나 버퍼를 간단히 추가
IEcsWorld	DI 서비스에서 ECS World와 EntityManager를 직접 참조하지 않고 사용
EntityManagerExtensions	TryGetComponent, SetOrAddComponent, GetOrAddBuffer 같은 반복 코드 제거

시스템에서 사용하기

SystemBase 대신 AchSystemBase를 상속합니다.

public struct Health : IComponentData
{
    public int Value;
}

public sealed partial class DamageSystem : AchSystemBase
{
    protected override void OnUpdate()
    {
        using var ecb = CreateCommandBuffer();

        foreach (var (health, entity) in
                 SystemAPI.Query<RefRW<Health>>().WithEntityAccess())
        {
            health.ValueRW.Value -= 1;

            if (health.ValueRO.Value <= 0)
            {
                ecb.Destroy(entity);
            }
        }

        ecb.Playback(EntityManager);
    }
}

EntityManager 확장 메서드

기존 EntityManager에 편의 메서드를 추가합니다.

EntityManager.SetOrAddComponent(entity, new Health { Value = 100 });

if (EntityManager.TryGetComponent<Health>(entity, out var health))
{
    UnityEngine.Debug.Log(health.Value);
}

EntityManager.RemoveComponentIfExists<Health>(entity);

Baker에서 사용하기

Baker<T> 대신 AchBaker<T>를 상속하면 Primary Entity에 컴포넌트를 붙이는 코드가 짧아집니다.

using AchEngine.ECS;
using Unity.Entities;
using UnityEngine;

public class CharacterAuthoring : MonoBehaviour
{
    public int Health = 100;
}

public class CharacterBaker : AchBaker<CharacterAuthoring>
{
    public override void Bake(CharacterAuthoring authoring)
    {
        AddComponentToPrimary(new Health { Value = authoring.Health });
    }
}

DI에서 ECS World 주입받기

씬의 AchEngineScope Installers에 AchEngineEcsInstaller를 추가하면 IEcsWorld를 서비스로 받을 수 있습니다.

using AchEngine.ECS;
using Unity.Entities;

public class SpawnService
{
    private readonly IEcsWorld _ecs;

    public SpawnService(IEcsWorld ecs)
    {
        _ecs = ecs;
    }

    public Entity Spawn(Entity prefab)
    {
        return _ecs.Instantiate(prefab);
    }
}

AchEngineEcsInstaller의 World Name을 비워두면 World.DefaultGameObjectInjectionWorld를 사용하고, 값을 입력하면 같은 이름의 World를 찾아 등록합니다.

